/**
 * Polices Noto Sans (subset latin) pour jsPDF.
 * Nom VFS strict: NotoSans. Depend de window.jspdf.
 * API: window.HQAppPdfFonts.register(doc)
 */
(function (root) {
    'use strict';
    var PDF_FONT_NAME = 'NotoSans';
    var FONTS = {
        normal: { file: 'NotoSans-Regular.ttf', data: '' },
        bold: { file: 'NotoSans-Bold.ttf', data: '' },
        italic: { file: 'NotoSans-Italic.ttf', data: '' }
    };
    function register(doc) {
        if (!doc || typeof doc.addFileToVFS !== 'function' || typeof doc.addFont !== 'function') return;
        var styles = Object.keys(FONTS);
        for (var i = 0; i < styles.length; i++) {
            var style = styles[i];
            var f = FONTS[style];
            doc.addFileToVFS(f.file, f.data);
            doc.addFont(f.file, PDF_FONT_NAME, style);
        }
        doc.setFont(PDF_FONT_NAME, 'normal');
    }
    root.HQAppPdfFonts = { PDF_FONT_NAME: PDF_FONT_NAME, register: register };
})(window);
